import sys
from collections import defaultdict

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    out_lines = []

    for _ in range(T):
        try:
            N = int(next(iterator))
            M = int(next(iterator))
        except StopIteration:
            break

        adj_destroyed = defaultdict(set)
        for _ in range(M):
            u = int(next(iterator))
            v = int(next(iterator))
            adj_destroyed[u].add(v)
            adj_destroyed[v].add(u)

        if N < 2:
            out_lines.append("0")
            continue

        def count_ways_for_X_set(S):
            if not S:
                return 0

            Y_set = set(range(1, N + 1)) - S
            if not Y_set:
                return 0

            for u in S:
                for v in S:
                    if u != v:
                        if v not in adj_destroyed[u]:
                            return 0

            for u in S:
                for v in Y_set:
                    if v in adj_destroyed[u]:
                        return 0

            return 1

        candidates = []
        for i in range(1, N + 1):
            neighbors_destroyed = adj_destroyed[i]
            count_destroyed = len(neighbors_destroyed)
            if count_destroyed == 0:
                candidates.append(i)
            elif count_destroyed == 1:
                candidates.append(i)

        valid_configs = 0

        if len(candidates) >= 2:
            for i in range(len(candidates)):
                for j in range(i + 1, len(candidates)):
                    u, v = candidates[i], candidates[j]
                    if v in adj_destroyed[u]:
                        continue

                    S = {u, v}
                    Y_set = set(range(1, N + 1)) - S

                    ok = True
                    for x in S:
                        for y in Y_set:
                            if y in adj_destroyed[x]:
                                ok = False
                                break
                        if not ok:
                            break

                    if ok:
                        valid_configs += 1

        if len(candidates) >= 3:
            pass

        if len(candidates) == 1:
            u = candidates[0]
            S = {u}
            Y_set = set(range(1, N + 1)) - {u}

            ok = True
            for y in Y_set:
                if y in adj_destroyed[u]:
                    ok = False
                    break
            if ok:
                valid_configs += 1

        if len(candidates) == 0:
            pass

        out_lines.append(str(valid_configs))

    sys.stdout.write('\n'.join(out_lines) + '\n')

if __name__ == "__main__":
    solve()
